mapper.select:
SELECT t.merchant_id, t.role, SUM(IF(t.role = 'PAYER', t.amount, 0)) as payout_amount, SUM(IF(t.role = 'PAYEE', t.amount, 0)) as receive_amount, SUM(IF(t.role = 'PAYEE', t.amount, 0)) - SUM(IF(t.role = 'PAYER', t.amount, 0)) as net_profit, COUNT(t.id) as record_count, m.merchant_name FROM (
SELECT id, payer_merchant_id as merchant_id, 'PAYER' as role, amount, status, created_time FROM joint_marketing_rebate_record WHERE plan_id = #{dto.planId} AND created_time BETWEEN #{dto.startDate} AND #{dto.endDate}
AND payer_merchant_id = #{dto.merchantId}
UNION ALL
SELECT id, payee_merchant_id as merchant_id, 'PAYEE' as role, amount, status, created_time FROM joint_marketing_rebate_record WHERE plan_id = #{dto.planId} AND created_time BETWEEN #{dto.startDate} AND #{dto.endDate}
AND payee_merchant_id = #{dto.merchantId}
) t LEFT JOIN merchant m ON t.merchant_id = m.id GROUP BY t.merchant_id, t.role, m.merchant_name ORDER BY net_profit DESC, record_count DESC

WITH merchant_profit AS ( SELECT m.id as merchantId, m.name AS merchantName, m.logo_url AS merchantLogo, m.industry_id, m.region_code, -- 总收益 = 接收总额 - 支付总额 SUM(IF(jmrr.payee_merchant_id = m.id, jmrr.amount, 0)) - SUM(IF(jmrr.payer_merchant_id = m.id, jmrr.amount, 0)) as total_profit, -- 支付总额 SUM(IF(jmrr.payer_merchant_id = m.id, jmrr.amount, 0)) as total_payout, -- 接收总额 SUM(IF(jmrr.payee_merchant_id = m.id, jmrr.amount, 0)) as total_receive, -- 交易次数 COUNT(jmrr.id) as transaction_count, -- 成功率 ROUND(SUM(IF(jmrr.status = 'SUCCESS', 1, 0)) * 100.0 / COUNT(jmrr.id), 2) as success_rate, -- 平均交易金额 ROUND(AVG(jmrr.amount), 2) as avg_amount FROM merchant m LEFT JOIN joint_marketing_rebate_record jmrr ON (jmrr.payer_merchant_id = m.id OR jmrr.payee_merchant_id = m.id) AND jmrr.created_time BETWEEN #{dto.startDate} AND #{dto.endDate} AND jmrr.status = 'SUCCESS'
AND jmrr.plan_id = #{dto.planId}
WHERE m.status = 'OPERATING'
AND m.industry_id = #{dto.industryId}
AND JSON_OVERLAPS(m.region_code -> '$[*]', CAST(#{dto.region} AS JSON))
GROUP BY merchantId, merchantName, industry_id ) SELECT merchantId, merchantName, merchantLogo, total_profit, total_payout, total_receive, transaction_count, success_rate, avg_amount FROM merchant_profit WHERE 1=1
AND total_profit > 0
ORDER BY total_profit DESC
LIMIT #{dto.limit}
